package com.familyfund.finance.internal.dto.response;

import com.familyfund.finance.api.dto.LedgerAnnualAuditStatus;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * Response representation of an annual ledger audit record, including either the auto-generated
 * US-15 adjustment request (when discrepant) or the closing rollover ledger entry (when matched).
 */
public record LedgerAnnualAuditResponse(
        String auditId,
        String clanId,
        Integer auditYear,
        Integer nextPeriodYear,
        Instant auditDate,
        BigDecimal systemBalance,
        BigDecimal actualBalance,
        BigDecimal discrepancyAmount,
        LedgerAnnualAuditStatus auditStatus,
        String referenceTransactionId,
        String adjustmentRequestId,
        String closingTransactionId,
        BigDecimal openingBalanceNextPeriod,
        String auditorAccountId,
        String auditorDisplayName,
        String notes,
        String evidenceAttachmentUrl,
        Instant createdAt,
        LedgerAdjustmentRequestResponse autoGeneratedAdjustmentRequest,
        ImmutableLedgerEntryResponse closingLedgerEntry
) {}
